// SCAFFOLD: genera 1 proposta demo. Da sostituire con scraper reali
// per Normattiva (https://www.normattiva.it/), EUR-Lex (https://eur-lex.europa.eu/),
// INAIL (https://www.inail.it/cs/internet/atti-e-documenti.html). Usare RSS
// quando disponibili o HTTP Request + Code parsing per HTML.
const now = new Date();
const sample = {
  sourceName: 'Normattiva (demo)',
  normTitle: 'Decreto Legislativo XX/2026 - Aggiornamento sicurezza chimica',
  normReference: 'D.Lgs. XX/2026, art. 5',
  normText: 'Esempio: introduce obbligo di formazione specifica per agenti chimici cancerogeni di categoria 1A/1B con cadenza biennale (era quinquennale).',
  changeSummary: 'Frequenza formazione cancerogeni 1A/1B: 5 anni -> 2 anni',
  fetchedAt: now.toISOString(),
  contentHash: 'demo-' + now.toISOString().slice(0, 10)
};
return [{ json: { proposal: sample } }];

const p = $input.first().json.proposal;
const systemPrompt = `Sei un esperto normativo HSE italiano. Analizza il testo normativo qui sotto e identifica TUTTI i nuovi/modificati obblighi per le checklist di sicurezza sul lavoro o igiene alimentare. Rispondi in JSON strict con la forma:
{"changes": [{"checklistType": "safety|haccp|both", "area": "string", "question": "string", "severity": 1-4, "sanctionable": true|false}]}
Nessun campo extra, no preambolo, solo JSON.`;
const userPrompt = `TITOLO: ${p.normTitle}
RIFERIMENTO: ${p.normReference}
TESTO: ${p.normText}
SINTESI CAMBIO: ${p.changeSummary}`;
return [{ json: { systemPrompt, userPrompt, proposal: p } }];

const aiResp = $input.first().json || {};
const content = aiResp.choices && aiResp.choices[0] && aiResp.choices[0].message ? aiResp.choices[0].message.content : '';
let parsed = { changes: [] };
try { parsed = JSON.parse(String(content || '{}')); } catch (e) { /* ignore */ }
const changes = Array.isArray(parsed.changes) ? parsed.changes : [];
const proposal = $items('Build AI Prompt')[0].json.proposal;
const payload = {
  sourceName: proposal.sourceName,
  normTitle: proposal.normTitle,
  normReference: proposal.normReference,
  normText: proposal.normText,
  changeSummary: proposal.changeSummary,
  proposedChanges: changes,
  contentHash: proposal.contentHash
};
return [{ json: { payload, hasChanges: changes.length > 0 } }];
